// Warmup + Benchmark helper
void Bench(string name, Action action, int warmupIters = 1000, int benchIters = 100_000)
{
    // Warmup
    for (int i = 0; i < warmupIters; i++) action();

    // Collect multiple samples
    var samples = new double[10];
    int itersPerSample = benchIters / samples.Length;
    for (int s = 0; s < samples.Length; s++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < itersPerSample; i++) action();
        sw.Stop();
        samples[s] = sw.Elapsed.TotalNanoseconds / itersPerSample;
    }

    Array.Sort(samples);
    double median = samples[samples.Length / 2];
    double mean = samples.Average();
    double min = samples[0];
    double max = samples[^1];

    Console.WriteLine($"{name,-25} | Mean: {mean,10:F2} ns | Median: {median,10:F2} ns | Min: {min,10:F2} ns | Max: {max,10:F2} ns");
}

Bench("AverageWordLength", () => { var r = analyzer.AverageWordLength(); });
Bench("WordLengthHistogram", () => { var r = analyzer.WordLengthHistogram(); });
Bench("UniqueWordCount",     () => { var r = analyzer.UniqueWordCount(); });

